create policy conversations_owner_or_member_read on public.conversations as restrictive for select to authenticated using(created_by=(select auth.uid()) or public.hayna_is_conversation_member(id,(select auth.uid()))); create policy conversations_creator_identity on public.conversations as restrictive for insert to authenticated with check(created_by=(select auth.uid())); create policy conversations_participant_delete on public.conversations as restrictive for delete to authenticated using(created_by=(select auth.uid()) or public.hayna_is_conversation_member(id,(select auth.uid()))); revoke all on public.conversations from public,anon;
